<?php
require_once dirname(__DIR__) . '/lib/DeploymentManager.php';
use DavvagDeveloper\ApplicationDiscovery;
use DavvagDeveloper\DependencyAnalyzer;
use DavvagDeveloper\DeploymentConfig;
use DavvagDeveloper\DeploymentManager;
use DavvagDeveloper\PackageBuilder;
use DavvagDeveloper\PackageImporter;
use DavvagDeveloper\SafeFiles;
use DavvagDeveloper\SecretScanner;
use DavvagDeveloper\ZipAdapter;

if (!class_exists('SOSSData')) { class SOSSData { public static $rows=array(); static function Query($n,$q){$r=(object)array('success'=>true,'result'=>array());if(isset(self::$rows[$n])){$parts=explode(':',$q,2);foreach(self::$rows[$n]as$row)if(isset($row->{$parts[0]})&&(string)$row->{$parts[0]}===(string)$parts[1])$r->result[]=$row;}return$r;}static function Insert($n,$row){if(!isset(self::$rows[$n]))self::$rows[$n]=array();self::$rows[$n][]=$row;return(object)array('success'=>true,'result'=>$row);}} }

$passed=0;$failed=0;
function check($condition,$name){global$passed,$failed;if($condition){$passed++;echo"PASS $name\n";}else{$failed++;echo"FAIL $name\n";}}
function write_json($path,$value){SafeFiles::writeJson($path,$value);}
function descriptor($title,$version,$deps=array()){return array('components'=>array(),'description'=>array('title'=>$title,'version'=>$version),'dependencies'=>array_merge(array('apps'=>array(),'schemas'=>array(),'workflows'=>array(),'plugins'=>array('local'=>array(),'global'=>array()),'php-extensions'=>array()),$deps));}
function stored_zip($path,$name,$data){$crc=crc32($data);$size=strlen($data);$local=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,0,$crc,$size,$size,strlen($name),0).$name.$data;$central=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,0,$crc,$size,$size,strlen($name),0,0,0,0,0,0).$name;$end=pack('VvvvvVVv',0x06054b50,0,0,1,1,strlen($central),strlen($local),0);file_put_contents($path,$local.$central.$end);}
$root=sys_get_temp_dir().'/davvag-deployment-tests-'.bin2hex(random_bytes(5));$tenant=$root.'/tenant/localhost';$appRoot=dirname(__DIR__);$storage=$root.'/storage';SafeFiles::mkdir($tenant.'/apps/app-a');SafeFiles::mkdir($tenant.'/apps/app-b');SafeFiles::mkdir($tenant.'/schemas/seed-data');SafeFiles::mkdir($tenant.'/davvag-flow/app-a');SafeFiles::mkdir($tenant.'/plugins/local-tool');SafeFiles::mkdir($root.'/plugins/global-tool');
write_json($tenant.'/tenant.json',array('apps'=>array('app-a'=>array('version'=>'latest'),'app-b'=>array('version'=>'latest'))));write_json($tenant.'/sysadmin.json',array('apps'=>array()));
write_json($tenant.'/apps/app-a/app.json',descriptor('App A','1.0.0',array('apps'=>array('app-b'),'schemas'=>array('app_items'),'workflows'=>array('app-a/run.json'),'plugins'=>array('local'=>array('local-tool'),'global'=>array('global-tool')),'php-extensions'=>array('json'))));
write_json($tenant.'/apps/app-b/app.json',descriptor('App B','1.0.0',array('schemas'=>array('shared_items'))));
write_json($tenant.'/schemas/app_items.json',array('fields'=>array(array('fieldName'=>'id','dataType'=>'int','annotations'=>array('isPrimary'=>true)))));write_json($tenant.'/schemas/shared_items.json',array('fields'=>array(array('fieldName'=>'id','dataType'=>'int','annotations'=>array('isPrimary'=>true)))));write_json($tenant.'/schemas/seed-data/app_items.json',array(array('id'=>1,'name'=>'Approved')));write_json($tenant.'/davvag-flow/app-a/run.json',array('name'=>'Run','start_up_node'=>'done'));
file_put_contents($tenant.'/plugins/local-tool/plugin.php','<?php return true;');file_put_contents($root.'/plugins/global-tool/plugin.php','<?php return true;');
$config=new DeploymentConfig($tenant,$appRoot,$storage);$discovery=new ApplicationDiscovery($config);$apps=$discovery->discover();check(count($apps)===2,'discovers registered applications');$analysis=(new DependencyAnalyzer($config))->analyze(array('app-a'));check(count($analysis['applications'])===2&&$analysis['buildable'],'resolves transitive app and shared dependencies');check(count($analysis['schemas'])===2,'deduplicates schema dependencies');check(count(array_filter($analysis['plugins'],function($p){return$p['classification']==='bundled-installable-plugin';}))===1,'classifies local plugin for bundling');check(count(array_filter($analysis['plugins'],function($p){return$p['classification']==='shared-framework-component';}))===1,'classifies global plugin as destination requirement');
$bad=descriptor('Bad','1.0.0',array('plugins'=>array('local'=>array('global-tool'),'global'=>array('local-tool'))));write_json($tenant.'/apps/app-b/app.json',$bad);$missing=(new DependencyAnalyzer($config))->analyze(array('app-b'));check(!$missing['buildable']&&count($missing['missing'])===2,'does not substitute local and global plugin scopes');$legacy=descriptor('Legacy','1.0.0',array('plugins'=>array('local-tool','global-tool')));write_json($tenant.'/apps/app-b/app.json',$legacy);$legacyAnalysis=(new DependencyAnalyzer($config))->analyze(array('app-b'));check($legacyAnalysis['buildable']&&count($legacyAnalysis['plugins'])===2,'supports legacy flat plugin arrays');
write_json($tenant.'/apps/app-a/app.json',descriptor('App A','1.0.0',array('apps'=>array('app-b'))));write_json($tenant.'/apps/app-b/app.json',descriptor('App B','1.0.0',array('apps'=>array('app-a'))));$cycle=(new DependencyAnalyzer($config))->analyze(array('app-a'));check(!$cycle['buildable']&&count($cycle['graph']['cycles'])===1,'detects dependency cycles');
write_json($tenant.'/apps/app-a/app.json',descriptor('App A','1.0.0',array('apps'=>array('app-b'),'schemas'=>array('app_items'),'workflows'=>array('app-a/run.json'),'plugins'=>array('local'=>array('local-tool'),'global'=>array('global-tool')),'php-extensions'=>array('json'))));write_json($tenant.'/apps/app-b/app.json',descriptor('App B','1.0.0',array('schemas'=>array('shared_items'))));
file_put_contents($tenant.'/apps/app-a/.env','PASSWORD="should-not-package"');check(count((new SecretScanner())->scan($tenant.'/apps/app-a'))===1,'detects sensitive files');unlink($tenant.'/apps/app-a/.env');
$builder=new PackageBuilder($config);$build=$builder->build(array('applications'=>array('app-a'),'package_name'=>'fixture-package','package_version'=>'1.0.0','profile'=>'staging','database_mode'=>'schema-safe-reference'));$artifact=$storage.'/artifacts/'.$build['artifact'];check(is_file($artifact)&&$build['status']==='complete','builds a real ZIP package');$inspect=(new PackageImporter($config))->inspect($artifact);check($inspect['valid']&&$inspect['manifest']['database']['mode']==='schema-safe-reference','verifies manifest and checksums');check(count(array_filter($inspect['manifest']['plugins'],function($p){return$p['source']==='local';}))===1&&count(array_filter($inspect['manifest']['plugins'],function($p){return$p['source']==='global';}))===1,'records scoped plugins in package manifest');
$malicious=$root.'/traversal.zip';stored_zip($malicious,'../outside.txt','bad');$blocked=false;try{(new ZipAdapter())->validate($malicious);}catch(Throwable$e){$blocked=true;}check($blocked,'rejects path traversal archive');
$corruptDir=$root.'/corrupt-package';(new ZipAdapter())->extract($artifact,$corruptDir);file_put_contents($corruptDir.'/manifest.json',"{}\n");$corrupt=$root.'/corrupt.zip';(new ZipAdapter())->create($corruptDir,$corrupt);$blocked=false;try{(new PackageImporter($config))->inspect($corrupt);}catch(Throwable$e){$blocked=true;}check($blocked,'rejects corrupted package');
$upload=(new PackageImporter($config))->upload($artifact,'fixture.zip');rename($root.'/plugins/global-tool',$root.'/plugins/global-tool-missing');$blockedPlan=(new PackageImporter($config))->plan($upload['token']);check(!$blockedPlan['installable']&&count(array_filter($blockedPlan['conflicts'],function($x){return$x['type']==='missing-global-plugin';}))===1,'blocks install when a required global plugin is missing');rename($root.'/plugins/global-tool-missing',$root.'/plugins/global-tool');$plan=(new PackageImporter($config))->plan($upload['token']);check($plan['installable'],'creates non-mutating installation plan');$install=(new PackageImporter($config))->install($upload['token'],array('approve_untrusted_code'=>true,'backup_confirmed'=>true,'activate'=>true));check($install['status']==='complete'&&in_array('registration',$install['checkpoints'],true),'installs with checkpoints and registration');check(count(SOSSData::$rows['app_items'])===1,'imports approved reference data idempotently');
SafeFiles::remove($root);echo"\n$passed passed, $failed failed\n";exit($failed?1:0);

